if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$location=trim((string)($_POST['location']??''));$latRaw=trim((string)($_POST['latitude']??''));$lngRaw=trim((string)($_POST['longitude']??''));try{if(mb_strlen($name)<2||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190||strlen($password)<8)throw new RuntimeException('Use a valid name/email and a password of at least 8 characters.');if(mb_strlen($location)>190)throw new RuntimeException('Location is too long.');$lat=null;if($latRaw!==''){if(!is_numeric($latRaw))throw new RuntimeException('Invalid latitude.');$lat=(float)$latRaw;if(!is_finite($lat)||$lat<-90||$lat>90)throw new RuntimeException('Latitude must be between -90 and 90.');}$lng=null;if($lngRaw!==''){if(!is_numeric($lngRaw))throw new RuntimeException('Invalid longitude.');$lng=(float)$lngRaw;if(!is_finite($lng)||$lng<-180||$lng>180)throw new RuntimeException('Longitude must be between -180 and 180.');}$s=db()->prepare("INSERT INTO users(name,email,password_hash,role,location,latitude,longitude) VALUES(?,?,?,'user',?,?,?)");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$location,$lat,$lng]);session_regenerate_id(true);$_SESSION['user_id']=(int)db()->lastInsertId();flash('success','Welcome to RADIUS.');redirect('/');}catch(PDOException$e){flash('error',$e->getCode()==='23000'?'That email is already registered.':'Registration failed.');}catch(RuntimeException$e){flash('error',$e->getMessage());}}
